CREATE TABLE accounts(id text PRIMARY KEY, status text NOT NULL DEFAULT 'idle' CHECK(status IN ('idle','online','rate_limited','disconnected','suspended','session_expired')), platform_user_id text UNIQUE, rate_limited_until timestamptz);
CREATE TABLE ws_clock(id integer PRIMARY KEY CHECK(id=1),seq bigint NOT NULL DEFAULT 0);
INSERT INTO ws_clock(id) VALUES(1);
CREATE TABLE ws_events(seq bigint PRIMARY KEY,type text NOT NULL,payload jsonb NOT NULL);
CREATE TABLE gateway_actions(id text PRIMARY KEY,account_id text NOT NULL REFERENCES accounts,action text NOT NULL,status text NOT NULL DEFAULT 'pending');
CREATE TABLE groups(id text PRIMARY KEY,gateway_group_id text UNIQUE,status text NOT NULL DEFAULT 'active',creator_account_id text NOT NULL REFERENCES accounts,agent_enabled boolean NOT NULL DEFAULT false,auto_kick_enabled boolean NOT NULL DEFAULT false);
CREATE TABLE members(group_id text NOT NULL REFERENCES groups,platform_user_id text NOT NULL,account_id text REFERENCES accounts,role text NOT NULL,PRIMARY KEY(group_id,platform_user_id));
CREATE TABLE jobs(id text PRIMARY KEY,kind text NOT NULL,group_id text REFERENCES groups,status text NOT NULL DEFAULT 'running',state jsonb NOT NULL,errors jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE messages(id bigserial PRIMARY KEY,group_id text NOT NULL REFERENCES groups,msg_id text,client_msg_id text UNIQUE,account_id text REFERENCES accounts,sender_platform_user_id text NOT NULL,is_own boolean NOT NULL,text text NOT NULL,sent_at timestamptz NOT NULL DEFAULT now(),delivery_status text,fail_code text,dispatch_started_at timestamptz,retry_count integer NOT NULL DEFAULT 0,reconcile_after timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(group_id,msg_id));
CREATE INDEX message_queue_account ON messages(account_id,id) WHERE delivery_status IN ('queued','dispatching','unknown');
CREATE TABLE gateway_inbox(event_id bigint PRIMARY KEY,type text NOT NULL,data jsonb NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),processed boolean NOT NULL DEFAULT false);
CREATE TABLE gateway_cursor(id integer PRIMARY KEY CHECK(id=1),event_id bigint NOT NULL DEFAULT 0);
INSERT INTO gateway_cursor(id) VALUES(1);
CREATE TABLE message_snapshots(id text PRIMARY KEY,group_id text NOT NULL REFERENCES groups,items jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sequences(id text PRIMARY KEY,name text NOT NULL,steps jsonb NOT NULL);
CREATE TABLE sequence_runs(id text PRIMARY KEY,group_id text NOT NULL REFERENCES groups,sequence_id text NOT NULL REFERENCES sequences,status text NOT NULL DEFAULT 'running',current_step_index integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_running_sequence ON sequence_runs(group_id) WHERE status='running';
CREATE TABLE sequence_steps(run_id text NOT NULL REFERENCES sequence_runs,index integer NOT NULL,status text NOT NULL DEFAULT 'pending',account_role text NOT NULL,text text NOT NULL,delay_seconds double precision NOT NULL,scheduled_at timestamptz,sent_at timestamptz,client_msg_id text REFERENCES messages(client_msg_id),resolved_vars jsonb NOT NULL,var_sources jsonb NOT NULL,PRIMARY KEY(run_id,index));
CREATE TABLE agent_runs(id text PRIMARY KEY,group_id text NOT NULL REFERENCES groups,status text NOT NULL DEFAULT 'running',end_reason text,summary text,history jsonb NOT NULL,steps jsonb NOT NULL DEFAULT '[]',pending jsonb,protocol_errors integer NOT NULL DEFAULT 0,elapsed_ms bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_running_agent ON agent_runs(group_id) WHERE status='running';
CREATE TABLE agent_pending(group_id text NOT NULL REFERENCES groups,msg_id text NOT NULL,PRIMARY KEY(group_id,msg_id));
CREATE TABLE agent_effects(run_id text NOT NULL REFERENCES agent_runs,key text NOT NULL,kind text NOT NULL,state text NOT NULL,client_msg_id text REFERENCES messages(client_msg_id),input jsonb NOT NULL,result jsonb,started_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(run_id,key));
